To create a desktop mask layer window using C++, you can follow these steps:

1. Include the necessary headers: 

```c++
#include <windows.h>
#include <tchar.h>
```

2. Define a window class and register it:

```c++
// This struct is used to hold the data of our window class
struct WindowClassData
{
    UINT style;
    WNDPROC lpfnWndProc;
    int cbClsExtra;
    int cbWndExtra;
    HINSTANCE hInstance;
    HICON hIcon;
    HCURSOR hCursor;
    HBRUSH hbrBackground;
    LPCTSTR lpszMenuName;
    LPCTSTR lpszClassName;
};

// Register the window class with the given data
void RegisterWindowClass(WindowClassData& wndClassData)
{
    WNDCLASS wc = {};
    wc.style = wndClassData.style;
    wc.lpfnWndProc = wndClassData.lpfnWndProc;
    wc.cbClsExtra = wndClassData.cbClsExtra;
    wc.cbWndExtra = wndClassData.cbWndExtra;
    wc.hInstance = wndClassData.hInstance;
    wc.hIcon = wndClassData.hIcon;
    wc.hCursor = wndClassData.hCursor;
    wc.hbrBackground = wndClassData.hbrBackground;
    wc.lpszMenuName = wndClassData.lpszMenuName;
    wc.lpszClassName = wndClassData.lpszClassName;

    RegisterClass(&wc);
}

// Create the window class data and register the window class
void CreateWindowClass(HINSTANCE hInstance, LPCTSTR className, WNDPROC wndProc)
{
    WindowClassData wndClassData = {};
    wndClassData.style = CS_HREDRAW | CS_VREDRAW;
    wndClassData.lpfnWndProc = wndProc;
    wndClassData.hInstance = hInstance;
    wndClassData.hCursor = LoadCursor(NULL, IDC_ARROW);
    wndClassData.hbrBackground = (HBRUSH)GetStockObject(BLACK_BRUSH);
    wndClassData.lpszClassName = className;

    RegisterWindowClass(wndClassData);
}
```

3. Create the main window:

```c++
HWND CreateMainWindow(HINSTANCE hInstance, LPCTSTR className, LPCTSTR windowTitle, int width, int height)
{
    HWND hWnd = CreateWindow(className, windowTitle, WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT, width, height, NULL, NULL, hInstance, NULL);

    if (!hWnd)
    {
        MessageBox(NULL, _T("Failed to create main window"), _T("Error"), MB_OK | MB_ICONERROR);
        return NULL;
    }

    ShowWindow(hWnd, SW_SHOW);
    UpdateWindow(hWnd);

    return hWnd;
}
```

4. Create a second window that will act as the mask layer:

```c++
HWND CreateMaskLayerWindow(HWND hParent, int x, int y, int width, int height)
{
    HWND hWnd = CreateWindow(_T("STATIC"), NULL, WS_CHILD | WS_VISIBLE | SS_BLACKRECT,
        x, y, width, height, hParent, NULL, (HINSTANCE)GetWindowLongPtr(hParent, GWLP_HINSTANCE), NULL);

    if (!hWnd)
    {
        MessageBox(hParent, _T("Failed to create mask layer window"), _T("Error"), MB_OK | MB_ICONERROR);
        return NULL;
    }

    SetWindowPos(hWnd, HWND_TOPMOST, 0, 0, 0, 0, SWP_NOMOVE | SWP_NOSIZE);

    return hWnd;
}
```

5. In the main window's WM_CREATE message handler, create the mask layer window:

```c++
case WM_CREATE:
{
    // Create the mask layer window
    HWND hMaskLayer = CreateMaskLayerWindow(hWnd, 0, 0, 800, 600);

    // Store the mask layer handle in the window's user data
    SetWindowLongPtr(hWnd, GWLP_USERDATA, (LONG_PTR)hMaskLayer);

    break;
}
```

6. In the main window's WM_PAINT message handler, draw your application's content normally and then draw a custom shape on the mask layer window to create the desired effect:

```c++
case WM_PAINT:
{
    PAINTSTRUCT ps;
    HDC hdc = BeginPaint(hWnd, &ps);

    // Draw your application's content normally here...

    // Get the mask layer window handle from the window's user data
    HWND hMaskLayer = (HWND)GetWindowLongPtr(hWnd, GWLP_USERDATA);

    // Draw the custom shape on the mask layer window
    HDC hMaskDc = GetDC(hMaskLayer);
    HBRUSH hMaskBrush = CreateSolidBrush(RGB(0, 0, 0));
    HBRUSH hOldBrush = (HBRUSH)SelectObject(hMaskDc, hMaskBrush);
    HPEN hOldPen = (HPEN)SelectObject(hMaskDc, GetStockObject(NULL_PEN));
    Ellipse(hMaskDc, 300, 200, 600, 500);
    SelectObject(hMaskDc, hOldPen);
    SelectObject(hMaskDc, hOldBrush);
    DeleteObject(hMaskBrush);
    ReleaseDC(hMaskLayer, hMaskDc);

    EndPaint(hWnd, &ps);
    break;
}
```

7. To update the mask layer window whenever the main window's size or position changes, handle the WM_WINDOWPOSCHANGED and WM_SIZE messages:

```c++
case WM_WINDOWPOSCHANGED:
case WM_SIZE:
{
    // Get the mask layer window handle from the window's user data
    HWND hMaskLayer = (HWND)GetWindowLongPtr(hWnd, GWLP_USERDATA);

    // Update the mask layer window's position and size to match the main window
    RECT rcClient;
    GetClientRect(hWnd, &rcClient);
    MapWindowPoints(hWnd, NULL, (LPPOINT)&rcClient, 2);
    SetWindowPos(hMaskLayer, HWND_TOPMOST, rcClient.left, rcClient.top, rcClient.right - rcClient.left, rcClient.bottom - rcClient.top, SWP_NOACTIVATE);

    break;
}
```

That's it! With these steps, you can create a desktop mask layer window that will overlay your application's main window and create a custom shape effect.

