Here is an example implementation of the WidebandSpectrumGenerator class in C++:

```
#include <vector>
#include <cmath>

struct Signal {
    double power;
    double frequency;
    double bandwidth;
};

class WidebandSpectrumGenerator {
public:
    WidebandSpectrumGenerator(double startFreq, double endFreq, double sampleRate, double noiseFloor, double signalToNoiseRatio, const std::vector<Signal>& signals);

    std::vector<double> generate();

private:
    double m_startFreq;
    double m_endFreq;
    double m_sampleRate;
    double m_noiseFloor;
    double m_signalToNoiseRatio;
    std::vector<Signal> m_signals;

    std::vector<double> addSignalToSpectrum(const Signal& signal, std::vector<double>& spectrum);
    std::vector<double> generateNoise();
    std::vector<double> calculateComplexSpectrum(const std::vector<double>& timeDomainSignal);
    std::vector<double> calculatePowerSpectrum(const std::vector<double>& complexSpectrum);
};

WidebandSpectrumGenerator::WidebandSpectrumGenerator(double startFreq, double endFreq, double sampleRate, double noiseFloor, double signalToNoiseRatio, const std::vector<Signal>& signals)
    : m_startFreq(startFreq), m_endFreq(endFreq), m_sampleRate(sampleRate), m_noiseFloor(noiseFloor), m_signalToNoiseRatio(signalToNoiseRatio), m_signals(signals) {}

std::vector<double> WidebandSpectrumGenerator::generate() {
    // Calculate the total number of samples to generate
    int numSamples = std::round((m_endFreq - m_startFreq) / m_sampleRate);

    // Generate the noise floor
    auto spectrum = generateNoise();

    // Add signals to the spectrum
    for (const auto& signal : m_signals) {
        spectrum = addSignalToSpectrum(signal, spectrum);
    }

    return spectrum;
}

std::vector<double> WidebandSpectrumGenerator::addSignalToSpectrum(const Signal& signal, std::vector<double>& spectrum) {
    // Calculate the number of samples needed for the signal
    int numSamples = std::round(signal.bandwidth / m_sampleRate);

    // Generate the time-domain signal
    std::vector<double> timeDomainSignal(numSamples);
    for (int i = 0; i < numSamples; i++) {
        timeDomainSignal[i] = std::cos(2.0 * M_PI * signal.frequency * i / m_sampleRate);
    }

    // Calculate the complex spectrum of the signal
    auto complexSpectrum = calculateComplexSpectrum(timeDomainSignal);

    // Calculate the power spectrum of the signal
    auto powerSpectrum = calculatePowerSpectrum(complexSpectrum);

    // Adjust the power of the signal based on the signal-to-noise ratio
    double signalPower = signal.power - m_noiseFloor + m_signalToNoiseRatio;
    for (auto& power : powerSpectrum) {
        power += signalPower;
    }

    // Add the signal power spectrum to the total spectrum
    for (int i = 0; i < spectrum.size(); i++) {
        spectrum[i] += powerSpectrum[i];
    }

    return spectrum;
}

std::vector<double> WidebandSpectrumGenerator::generateNoise() {
    // Calculate the total number of samples to generate
    int numSamples = std::round((m_endFreq - m_startFreq) / m_sampleRate);

    // Generate white Gaussian noise
    std::vector<double> noise(numSamples);
    for (auto& sample : noise) {
        sample = std::sqrt(-2.0 * std::log(rand() / (RAND_MAX + 1.0))) * std::cos(2.0 * M_PI * rand() / (RAND_MAX + 1.0));
    }

    // Convert the noise to a power spectrum
    auto spectrum = calculatePowerSpectrum(calculateComplexSpectrum(noise));

    // Adjust the noise floor based on the input dBm level
    double noiseFloorPower = std::pow(10.0, m_noiseFloor / 10.0);
    double noisePower = 0.0;
    for (auto& power : spectrum) {
        noisePower += std::pow(10.0, power / 10.0);
    }
    double scale = std::sqrt(noiseFloorPower / noisePower);
    for (auto& power : spectrum) {
        power += 10.0 * std::log10(scale);
    }

    return spectrum;
}

std::vector<double> WidebandSpectrumGenerator::calculateComplexSpectrum(const std::vector<double>& timeDomainSignal) {
    // Calculate the FFT of the time-domain signal
    std::vector<std::complex<double>> complexSignal(timeDomainSignal.size());
    for (int i = 0; i < timeDomainSignal.size(); i++) {
        complexSignal[i] = std::complex<double>(timeDomainSignal[i], 0.0);
    }
    std::vector<std::complex<double>> complexSpectrum(complexSignal.size() / 2 + 1);
    fftw_plan plan = fftw_plan_dft_r2c_1d(complexSignal.size(), &complexSignal[0].real(), reinterpret_cast<fftw_complex*>(&complexSpectrum[0]), FFTW_ESTIMATE);
    fftw_execute(plan);
    fftw_destroy_plan(plan);

    // Convert the complex spectrum to a vector of magnitudes
    std::vector<double> powerSpectrum(complexSpectrum.size());
    for (int i = 0; i < powerSpectrum.size(); i++) {
        powerSpectrum[i] = std::abs(complexSpectrum[i]);
    }

    return powerSpectrum;
}

std::vector<double> WidebandSpectrumGenerator::calculatePowerSpectrum(const std::vector<double>& complexSpectrum) {
    // Convert the complex spectrum to a power spectrum
    std::vector<double> powerSpectrum(complexSpectrum.size());
    for (int i = 0; i < powerSpectrum.size(); i++) {
        powerSpectrum[i] = 20.0 * std::log10(complexSpectrum[i]);
    }

    return powerSpectrum;
}
