Here is an implementation example in C++ that demonstrates how to retrieve a file from Outlook using CFSTR_FILECONTENTS data format:

```
// Define the data formats to be used in the drag-and-drop operation.
const FORMATETC fe[] = { { CF_HDROP, NULL, DVASPECT_CONTENT, -1, TYMED_HGLOBAL },
                         { CF_FILECONTENTS, NULL, DVASPECT_CONTENT, -1, TYMED_HGLOBAL } };

// Handle the DragEnter event in the Outlook application.
HRESULT STDMETHODCALLTYPE MyDragEnter(IDataObject* pDataObj, DWORD grfKeyState, 
                                        POINTL pt, DWORD* pdwEffect)
{
    FORMATETC* pfe = fe;
    STGMEDIUM medium;

    HRESULT hr = pDataObj->QueryGetData(&pfe[0]);
    if (hr != S_OK) {
        return hr; // The file cannot be retrieved.
    }

    // Get the file information
    hr = pDataObj->GetData(&pfe[0], &medium);
    if (hr != S_OK) {
        return hr; // Failed to get data.
    }

    // Extract file path and name from the data
    HDROP hDrop = (HDROP)medium.hGlobal;
    UINT uNumFiles = DragQueryFile(hDrop, 0xFFFFFFFF, NULL, 0);
    for (UINT i = 0; i < uNumFiles; i++) {
        TCHAR szFilename[MAX_PATH] = {};
        DragQueryFile(hDrop, i, szFilename, MAX_PATH);
        // Copy the file to the desired location.
        // ...

        // Retrieve the file contents.
        hr = pDataObj->GetData(&pfe[1], &medium);
        if (hr != S_OK) {
            return hr; // Failed to get data.
        }
        LPVOID lpData = GlobalLock(medium.hGlobal);
        DWORD dwSize = GlobalSize(medium.hGlobal);
        // Process the file contents.
        // ...

        GlobalUnlock(medium.hGlobal);
        ReleaseStgMedium(&medium);
    }

    return S_OK; // Success.
}
```

This code uses the "fe" array to define the supported data formats, i.e., CF_HDROP and CF_FILECONTENTS. It then checks if the "CF_HDROP" data format is available to extract the file information. If successful, it copies the file to the desired location and retrieves the file contents using the "CF_FILECONTENTS" data format. Finally, it uses the extracted data to perform necessary operations.

Note that this code is just an example, and you need to customize it as per your needs. Also, make sure to include the necessary header files and libraries required for this code to compile successfully.

