```javascript
// src/httpClient.js
import axios from 'axios';

const httpClient = axios.create({
  baseURL: 'https://your-base-url.com/api/', // Replace with your base API URL
  headers: {
    'Content-Type': 'application/json',
  },
});

httpClient.interceptors.request.use(
  (config) => {
    // Add logic for request manipulation here if necessary
    // For example, add an authentication token to the headers
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

httpClient.interceptors.response.use(
  (response) => {
    // Process the response if necessary
    return response;
  },
  (error) => {
    if (error.response && error.response.status === 401) {
      // Handle unauthorized errors, such as needing to log in again
      // For example, clear user data and redirect to login page
    }
    return Promise.reject(error);
  }
);

const get = async (url, config = {}) => {
  try {
    const response = await httpClient.get(url, config);
    return response.data;
  } catch (error) {
    console.error(`Error fetching data from ${url}:`, error.message);
    throw error;
  }
};

const post = async (url, data, config = {}) => {
  try {
    const response = await httpClient.post(url, data, config);
    return response.data;
  } catch (error) {
    console.error(`Error posting data to ${url}:`, error.message);
    throw error;
  }
};

export default {
  ...httpClient,
  get,
  post
};
