		edges[i] = (int) Math.sqrt(gx * gx + gy * gy);
		}

		int[] thresholdEdges = applyHysteresis(edges, lowThreshold, highThreshold, width, height);

		for (int i = 0; i < pixels.length; i++) {
		if (thresholdEdges[i] != 0) {
		resultImage.setRGB(i % width, i / width, 0);
		} else {
