		}
		}

		return resultImage;
		}

		private int[] applyHysteresis(int[] edges, int low, int high, int width, int height) {
		int[] result = new int[edges.length];
		Arrays.fill(result, 0);
		for (int i = 0; i < edges.length; i++) {
		if (edges[i] >= high && result[i] == 0) {
