{
    // Load a bitmap file
    HBITMAP hBitmap = LoadBitmapFromFile(L"mybitmap.bmp");

    // Display the bitmap using layered window with scaling
    HWND hWnd = CreateWindow(L"MyWindowClass", L"My Window", WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT, CW_USEDEFAULT, CW_USEDEFAULT, NULL, NULL, hInstance, NULL);
    DisplayScaledBitmap(hWnd, hBitmap, 0, 0, 200, 100, 0, 0, 100, 50);   // scale to 200x100 and display at (0,0)
    ShowWindow(hWnd, nShowCmd);

    // Run the message loop
    MSG msg;
    while (GetMessage(&msg, NULL, 0, 0))
    {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // Clean up
    DeleteObject(hBitmap);
    return 0;
}
